from pydantic import RootModel

class MyRootModel(RootModel):
    root: int

# Let's monkey patch to trace
import pydantic.main as main

orig_model_construct = main.BaseModel.model_construct

@classmethod
def traced_model_construct(cls, _fields_set=None, **values):
    print('=== model_construct called ===')
    m = cls.__new__(cls)
    fields_values = {}
    defaults = {}
    for name, field in cls.model_fields.items():
        if field.alias and field.alias in values:
            fields_values[name] = values.pop(field.alias)
        elif name in values:
            fields_values[name] = values.pop(name)
        elif not field.is_required():
            defaults[name] = field.get_default(call_default_factory=True)
    if _fields_set is None:
        _fields_set = set(fields_values.keys())
    fields_values.update(defaults)

    _extra = None
    if cls.model_config.get('extra') == 'allow':
        _extra = {}
        for k, v in values.items():
            _extra[k] = v
    else:
        fields_values.update(values)

    print(f'Before setting __dict__, fields_values={fields_values}')
    main._object_setattr(m, '__dict__', fields_values)
    print(f'After setting __dict__, m.__dict__={m.__dict__}')

    main._object_setattr(m, '__pydantic_fields_set__', _fields_set)
    print(f'After setting fields_set, m.__dict__={m.__dict__}')

    main._object_setattr(m, '__pydantic_extra__', _extra)
    print(f'After setting extra, m.__dict__={m.__dict__}')

    if cls.__pydantic_post_init__:
        m.model_post_init(None)
    else:
        main._object_setattr(m, '__pydantic_private__', None)
        print(f'After setting private, m.__dict__={m.__dict__}')

    print('=== model_construct returning ===')
    return m

main.BaseModel.model_construct = traced_model_construct
m = MyRootModel.model_construct(42)
print()
print('Final m.__dict__:', m.__dict__)
